# 原地交换法：不用 used，直接在原数组上换位
class Solution:
    def permute(self, nums):
        res = []
        n = len(nums)

        def dfs(start):
            if start == n:
                res.append(nums[:])
                return
            for i in range(start, n):
                nums[start], nums[i] = nums[i], nums[start]
                dfs(start + 1)
                nums[start], nums[i] = nums[i], nums[start]  # 恢复

        dfs(0)
        return res
